def count_3x3_blocks(grid, color):
    """Count 3x3 blocks that contain only the given color"""
    count = 0
    for r in range(len(grid) - 2):
        for c in range(len(grid[0]) - 2):
            block = [grid[r+dr][c+dc] for dr in range(3) for dc in range(3)]
            if all(cell == color for cell in block):
